-- ─── 12. `usage_hourly` materialized view ─────────────────────────────────
-- DEVIATION (Wave 1): Neon ships TimescaleDB Apache edition (community), which
-- does NOT support continuous aggregates (`WITH (timescaledb.continuous)` and
-- `add_continuous_aggregate_policy` are TSL-licensed features). We fall back
-- to a regular PostgreSQL MATERIALIZED VIEW with manual REFRESH, driven by an
-- Inngest cron in Wave 2 (stripe-meters-emit-v1). API surface is unchanged —
-- downstream consumers only `SELECT FROM usage_hourly`. Documented in
-- 08-PHASE-DEVIATIONS.md (Plan 05 Task 2).
--
-- Read by the Stripe meters emitter (D-25) and the dashboard usage chart.
CREATE MATERIALIZED VIEW "usage_hourly" AS
SELECT
  time_bucket('1 hour', "time") AS bucket,
  "deployment_id",
  count(*) AS event_count,
  sum(coalesce("tokens_in", 0))::bigint AS tokens_in_total,
  sum(coalesce("tokens_out", 0))::bigint AS tokens_out_total,
  sum(case when "status" = 'error' then 1 else 0 end)::int AS error_count
FROM "usage_events"
GROUP BY bucket, "deployment_id"
WITH NO DATA;
--> statement-breakpoint
CREATE UNIQUE INDEX "usage_hourly_pk" ON "usage_hourly"(bucket, "deployment_id");--> statement-breakpoint

-- ─── 13. COMMENT ON COLUMN rows (operator-facing docs) ────────────────────
COMMENT ON COLUMN "organizations"."quota_period_start" IS 'Anchor timestamp for monthly quota windows; rolled forward by quota-period-rollover-v1 Inngest function.';
COMMENT ON COLUMN "generations"."cumulative_cost_usd" IS 'Running sum of LLM spend on this generation; cost-cap-enforcer-v1 cancels when > free $0.50 / pro $2.00.';
COMMENT ON COLUMN "generations"."triggered_by" IS 'user | drift_auto | drift_manual — distinguishes user-initiated vs drift-watcher regenerations.';
COMMENT ON COLUMN "deployments"."auto_regenerate_on_drift" IS 'When true, Drift Watcher creates a new generation automatically; otherwise emits drift_event with status=pending.';
